def conf_for(protocol: str, action: str) -> dict:
    if protocol == "ocpp2.1":
        if action in CONF_21:
            return dict(CONF_21[action])
        return dict(CONF_201[action]) if action in CONF_201 else {}
    table = CONF_201 if protocol == "ocpp2.0.1" else CONF_16
    return dict(table[action]) if action in table else {}


def req_for(protocol: str, action: str) -> dict:
    if protocol == "ocpp2.1":
        if action in REQ_21:
            return dict(REQ_21[action])
        return dict(REQ_201[action]) if action in REQ_201 else {}
    table = REQ_201 if protocol == "ocpp2.0.1" else REQ_16
    return dict(table[action]) if action in table else {}


def from_cp(protocol: str) -> tuple[str, ...]:
    if protocol == "ocpp2.1":
        return tuple(list(FROM_CP_201) + list(FROM_CP_21))
    return tuple(FROM_CP_201 if protocol == "ocpp2.0.1" else FROM_CP_16)


def from_csms(protocol: str) -> tuple[str, ...]:
    if protocol == "ocpp2.1":
        return tuple(list(FROM_CSMS_201) + list(FROM_CSMS_21))
    return tuple(FROM_CSMS_201 if protocol == "ocpp2.0.1" else FROM_CSMS_16)
